{
  "primary_meaning": "Any thought, word, deed, or disposition that transgresses God's law, misses the divine standard (hamartia), or rebels against God, producing guilt and separation from Him",
  "primary_basis": [
    "Romans 3:23",
    "1 John 3:4",
    "Romans 6:23",
    "Isaiah 59:2",
    "Genesis 3"
  ],
  "alternatives": [
    {
      "meaning": "Inherited Adamic condition of guilt and corruption (original sin) transmitted to all humanity",
      "basis": [
        "Romans 5:12-19",
        "Psalm 51:5",
        "Ephesians 2:3"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A personified cosmic power or enslaving force that dwells in and dominates human nature",
      "basis": [
        "Romans 6:6-23",
        "Romans 7:7-25",
        "John 8:34"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Primarily a relational rupture or spiritual sickness/alienation rather than forensic legal guilt",
      "basis": [
        "Luke 15 (prodigal son)",
        "Eastern Orthodox therapeutic tradition",
        "Isaiah 1:5-6"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across historic Christian confessions the core denotation of sin as moral failure relative to God's will is settled; differences concern transmission, ontology, and juridical vs. therapeutic emphasis rather than the basic meaning itself."
}
